beginning.embedded_functions:
static unsigned long int number_patterns = 0;
static int pattern_index = 0;

static char *ae_title_patterns[] = {
    "DCM4CHEE",
    "CONQUESTSRV1",
    "STORESCP",
    "MYPACS",
    "VIEWER",
    "OSIRIX",
    "HOROS",
    "PACSONE",
    "DCMROUTER",
    "WORKSTATION",
    "12345678901234",
    "LOWERCASE",
    "A",
    "TOOLONGAETITLE16",
    "",
    "INVALID!@#$%",
    "WAYTOOLONGAETITLEOVER16CHARS",
    "     ",
    "ORTHANC",
    "MODALITY",
};

void on_load() {
    number_patterns = sizeof(ae_title_patterns) / sizeof(ae_title_patterns[0]);
    pattern_index = 0;
}

static void em_fuzz_dicom_ae_titles(
    const rule_info_t *rule, int verdict, uint64_t timestamp,
    uint64_t counter, const mmt_array_t * const trace) {

    if (pattern_index >= number_patterns)
        pattern_index = 0;

    char *ae_title = ae_title_patterns[pattern_index];
    replace_dicom_attribute(701, 4, ae_title, 1);
    pattern_index++;
    forward_packet();
}
